import React, { useState } from "react";
import { Outlet } from "react-router-dom";
import Sidebar from "./Sidebar";
import TopHeader from "./TopHeader";
import { useApp } from "../../lib/AppContext";

const AdminLayout = () => {
  const [menuOpen, setMenuOpen] = useState(false);
  const { notify } = useApp();

  return (
    <div className="min-h-screen bg-[#f7f9f7] font-sans text-[#17221c]">
      <Sidebar open={menuOpen} onClose={() => setMenuOpen(false)} />
      {menuOpen && (
        <button
          aria-label="Close navigation"
          className="fixed inset-0 z-20 bg-black/30 lg:hidden"
          onClick={() => setMenuOpen(false)}
        />
      )}
      <main className="flex min-h-screen flex-col lg:ml-[248px]">
        <TopHeader onMenu={() => setMenuOpen(true)} notify={notify} />
        <div className="mx-auto w-full max-w-[1600px] flex-1 px-3 py-5 sm:px-5 lg:px-9 lg:py-7">
          <Outlet />
        </div>
        <footer className="flex min-h-11 flex-wrap items-center justify-between gap-2 border-t border-gray-100 bg-white px-4 text-[9px] text-gray-400 sm:px-8">
          <span>
            © 2025 CEGCT · Community Environmental Guardian & Cleanliness Tracker
          </span>
          <span className="flex items-center gap-2 text-gray-500">
            <i className="h-1.5 w-1.5 rounded-full bg-green-500" />
            All systems operational
          </span>
        </footer>
      </main>
    </div>
  );
};

export default AdminLayout;
